// ═══════════════════════════════════════════════════════════
// CONFIGURATION
// Every value is read from an environment variable. Credentials do not
// belong in the flow, and therefore not in the repository.
// ═══════════════════════════════════════════════════════════
const cfg = {
    // In the browser Odoo shows an address with /odoo or /web appended.
    // The JSON-RPC endpoint sits at the bare server address, so path
    // remnants and a trailing slash are removed.
    odooUrl:    String(env.get('SDI_ODOO_URL') || 'http://localhost:8069')
                    .trim().replace(/\/+(odoo|web)\/?$/i, '').replace(/\/+$/, ''),
    db:         env.get('SDI_ODOO_DB')     || '',
    user:       env.get('SDI_ODOO_USER')   || '',
    apiKey:     env.get('SDI_ODOO_APIKEY') || '',
    productName: env.get('SDI_ODOO_PRODUCT') || 'Kugelschreiber TRACEpen',
    flowField:  env.get('SDI_ODOO_FLOW_FIELD') || 'x_studio_lca_flow_uuid',
    materialField: env.get('SDI_ODOO_MATERIAL_FIELD') || 'x_lca_material',
    processField:  env.get('SDI_ODOO_PROCESS_FIELD')  || 'x_lca_process_id',
    parameterField: env.get('SDI_ODOO_PARAMETER_FIELD') || 'x_lca_parameter',
    zeroField:     env.get('SDI_ODOO_ZERO_FIELD')     || 'x_lca_zero_parameters',
    aasUrl:     env.get('SDI_AAS_URL')     || 'http://localhost:8081',
    submodelId: env.get('SDI_AAS_DATASOURCES_ID')
                || 'localhost/demo/aas/Kugelschreiber_TracePEN/DataSources'
};

if (!cfg.db || !cfg.user || !cfg.apiKey) {
    node.error('SDI_ODOO_DB, SDI_ODOO_USER and SDI_ODOO_APIKEY have to be set', msg);
    return null;
}

flow.set('cfg', cfg);

msg.url = cfg.odooUrl + '/jsonrpc';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    jsonrpc: '2.0', method: 'call', id: 1,
    params: { service: 'common', method: 'authenticate',
              args: [cfg.db, cfg.user, cfg.apiKey, {}] }
};
node.status({ fill: 'blue', shape: 'dot', text: 'Login ' + cfg.db });
return msg;

// Check the uid and find the bill of material of the product
const cfg = flow.get('cfg');
if (msg.payload && msg.payload.error) {
    node.error('Odoo login failed: ' + JSON.stringify(msg.payload.error), msg);
    return null;
}
const uid = msg.payload ? msg.payload.result : null;
if (!uid) {
    node.error('Odoo authentication returned no uid - check the credentials', msg);
    return null;
}
cfg.uid = uid;
flow.set('cfg', cfg);
node.log('Odoo login ok, uid=' + uid);

// Builds an Odoo JSON-RPC call (the counterpart of execute_kw in the XML-RPC API)
function rpc(cfg, model, method, args, kwargs) {
    return {
        jsonrpc: '2.0', method: 'call', id: Date.now(),
        params: {
            service: 'object', method: 'execute_kw',
            args: [cfg.db, cfg.uid, cfg.apiKey, model, method, args, kwargs || {}]
        }
    };
}

// Fetch the product template and its bill of material in one call
msg.url = cfg.odooUrl + '/jsonrpc';
msg.headers = { 'Content-Type': 'application/json' };
// Find the product by name, article number or part of the name. The search
// then works whether SDI_ODOO_PRODUCT holds the designation
// ("Kugelschreiber_TracePEN") or the number ("000114").
msg.payload = rpc(cfg, 'mrp.bom', 'search_read',
    [[ '|', '|',
       ['product_tmpl_id.name', '=', cfg.productName],
       ['product_tmpl_id.default_code', '=', cfg.productName],
       ['product_tmpl_id.name', 'ilike', cfg.productName],
       ['type', '=', 'normal'] ]],
    { fields: ['product_tmpl_id', 'product_qty', 'bom_line_ids'], limit: 1 });
node.status({ fill: 'blue', shape: 'dot', text: 'finding bill of material' });
return msg;

// Evaluate the bill-of-material header, fetch its lines
const cfg = flow.get('cfg');
if (msg.payload && msg.payload.error) {
    node.error('Odoo error (mrp.bom): ' + JSON.stringify(msg.payload.error), msg);
    return null;
}
const boms = msg.payload.result || [];
if (boms.length === 0) {
    node.error('No bill of material for product "' + cfg.productName +
        '" found (searched by name, article number and part of the name)', msg);
    return null;
}
const bom = boms[0];
flow.set('bomHeader', bom);
const lineIds = bom.bom_line_ids || [];
if (lineIds.length === 0) {
    node.error('The bill of material has no lines', msg);
    return null;
}
node.log('Bill of material ' + bom.id + ' with ' + lineIds.length + ' lines');

// Builds an Odoo JSON-RPC call (the counterpart of execute_kw in the XML-RPC API)
function rpc(cfg, model, method, args, kwargs) {
    return {
        jsonrpc: '2.0', method: 'call', id: Date.now(),
        params: {
            service: 'object', method: 'execute_kw',
            args: [cfg.db, cfg.uid, cfg.apiKey, model, method, args, kwargs || {}]
        }
    };
}

msg.url = cfg.odooUrl + '/jsonrpc';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = rpc(cfg, 'mrp.bom.line', 'read', [lineIds],
    { fields: ['product_id', 'product_tmpl_id', 'product_qty'] });
return msg;

// Keep the lines, read every product template needed in one go
const cfg = flow.get('cfg');
if (msg.payload && msg.payload.error) {
    node.error('Odoo error (mrp.bom.line): ' + JSON.stringify(msg.payload.error), msg);
    return null;
}
const lines = msg.payload.result || [];
flow.set('bomLines', lines);

const header = flow.get('bomHeader');
const tmplIds = new Set();
if (header.product_tmpl_id) { tmplIds.add(header.product_tmpl_id[0]); }
lines.forEach(l => { if (l.product_tmpl_id) { tmplIds.add(l.product_tmpl_id[0]); } });

// Builds an Odoo JSON-RPC call (the counterpart of execute_kw in the XML-RPC API)
function rpc(cfg, model, method, args, kwargs) {
    return {
        jsonrpc: '2.0', method: 'call', id: Date.now(),
        params: {
            service: 'object', method: 'execute_kw',
            args: [cfg.db, cfg.uid, cfg.apiKey, model, method, args, kwargs || {}]
        }
    };
}

msg.url = cfg.odooUrl + '/jsonrpc';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = rpc(cfg, 'product.template', 'read', [Array.from(tmplIds)],
    { fields: ['name', 'default_code', 'weight', 'categ_id', 'uom_id',
               cfg.flowField, cfg.materialField, cfg.processField,
               cfg.parameterField, cfg.zeroField] });
return msg;

// Keep the templates, fetch the variants (fallback for weight and flow uuid)
const cfg = flow.get('cfg');
if (msg.payload && msg.payload.error) {
    node.error('Odoo error (product.template): ' + JSON.stringify(msg.payload.error), msg);
    return null;
}
const tmplById = {};
(msg.payload.result || []).forEach(t => { tmplById[t.id] = t; });
flow.set('tmplById', tmplById);

const lines = flow.get('bomLines') || [];
const variantIds = lines.filter(l => l.product_id).map(l => l.product_id[0]);

// Builds an Odoo JSON-RPC call (the counterpart of execute_kw in the XML-RPC API)
function rpc(cfg, model, method, args, kwargs) {
    return {
        jsonrpc: '2.0', method: 'call', id: Date.now(),
        params: {
            service: 'object', method: 'execute_kw',
            args: [cfg.db, cfg.uid, cfg.apiKey, model, method, args, kwargs || {}]
        }
    };
}

msg.url = cfg.odooUrl + '/jsonrpc';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = rpc(cfg, 'product.product', 'read', [variantIds],
    { fields: ['display_name', 'weight', 'product_tmpl_id', cfg.flowField] });
return msg;

// Merge the bill of material and ask for the manufacturing order
//
// Rules following MA 468 (Rajab), chapter 5.3:
//   - flow uuid: the template is preferred, the variant is the fallback
//   - weight:    the template is the base, a variant overrides it if kept
//   - total mass = weight per piece * quantity
const cfg = flow.get('cfg');
if (msg.payload && msg.payload.error) {
    node.error('Odoo error (product.product): ' + JSON.stringify(msg.payload.error), msg);
    return null;
}
const variantById = {};
(msg.payload.result || []).forEach(v => { variantById[v.id] = v; });

const tmplById = flow.get('tmplById') || {};
const lines = flow.get('bomLines') || [];
const header = flow.get('bomHeader');

const components = [];
const skipped = [];

lines.forEach(line => {
    const qty = line.product_qty || 0;
    const tmpl = line.product_tmpl_id ? tmplById[line.product_tmpl_id[0]] : null;
    const variant = line.product_id ? variantById[line.product_id[0]] : null;

    let name = (tmpl && tmpl.name) || (variant && variant.display_name) || null;
    if (!name) { name = 'Line ' + line.id; }

    let flowUuid = (tmpl && tmpl[cfg.flowField]) || null;
    if (!flowUuid && variant && variant[cfg.flowField]) { flowUuid = variant[cfg.flowField]; }

    let weightKg = (tmpl && tmpl.weight) || 0;
    if (variant && variant.weight) { weightKg = variant.weight; }

    const reasons = [];
    if (!flowUuid) { reasons.push('no ' + cfg.flowField); }
    if (!weightKg || weightKg <= 0) { reasons.push('no valid weight'); }
    if (reasons.length > 0) {
        skipped.push(name + ' (' + reasons.join(', ') + ')');
        return;
    }

    components.push({
        name: name,
        productCode: (tmpl && tmpl.default_code) || '',
        quantity: qty,
        quantityUnit: (tmpl && tmpl.uom_id && tmpl.uom_id[1]) || '',
        weightKg: weightKg,
        totalMassKg: weightKg * qty,
        material: (tmpl && tmpl[cfg.materialField]) || '',
        lcaProcessId: (tmpl && tmpl[cfg.processField]) || '',
        lcaParameter: (tmpl && tmpl[cfg.parameterField]) || '',
        lcaZeroParameters: (tmpl && tmpl[cfg.zeroField]) || '',
        materialCategory: (tmpl && tmpl.categ_id && tmpl.categ_id[1]) || '',
        lcaFlowId: flowUuid
    });
});

if (skipped.length > 0) { node.warn('Skipped lines: ' + skipped.join('; ')); }
if (components.length === 0) {
    node.error('No usable bill-of-material line found', msg);
    return null;
}

const prodTmpl = header.product_tmpl_id ? tmplById[header.product_tmpl_id[0]] : null;
flow.set('erp', {
    productName: (prodTmpl && prodTmpl.name) || cfg.productName,
    productCode: (prodTmpl && prodTmpl.default_code) || '',
    productWeightKg: (prodTmpl && prodTmpl.weight) || 0,
    bomId: header.id,
    bomQuantity: header.product_qty || 1,
    components: components,
    skipped: skipped
});
node.log('Bill of material merged: ' + components.length + ' lines');

// Builds an Odoo JSON-RPC call (the counterpart of execute_kw in the XML-RPC API)
function rpc(cfg, model, method, args, kwargs) {
    return {
        jsonrpc: '2.0', method: 'call', id: Date.now(),
        params: {
            service: 'object', method: 'execute_kw',
            args: [cfg.db, cfg.uid, cfg.apiKey, model, method, args, kwargs || {}]
        }
    };
}

msg.url = cfg.odooUrl + '/jsonrpc';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = rpc(cfg, 'mrp.production', 'search_read',
    [[ '|', '|',
       ['product_id.product_tmpl_id.name', '=', cfg.productName],
       ['product_id.product_tmpl_id.default_code', '=', cfg.productName],
       ['product_id.product_tmpl_id.name', 'ilike', cfg.productName],
       ['state', 'in', ['confirmed', 'progress', 'to_close', 'done']] ]],
    { fields: ['name', 'product_qty', 'state'], limit: 1 });
return msg;

// Take over the order data (optional) and load the DataSources submodel
const cfg = flow.get('cfg');
const erp = flow.get('erp');

if (msg.payload && msg.payload.error) {
    node.warn('Manufacturing order cannot be read, carrying on without order data');
} else {
    const mos = msg.payload.result || [];
    if (mos.length > 0) {
        erp.order = {
            number: mos[0].name,
            quantity: mos[0].product_qty,
            unit: erp.components.length ? erp.components[0].quantityUnit : '',
            state: mos[0].state
        };
        node.log('Manufacturing order ' + erp.order.number + ' over ' + erp.order.quantity + ' pieces');
    } else {
        node.log('No open manufacturing order found');
    }
}
erp.retrievedAt = new Date().toISOString();
flow.set('erp', erp);

// Encode the AAS identifier as base64url (required by the AAS Part 2 API)
const b64 = Buffer.from(cfg.submodelId, 'utf8').toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
flow.set('submodelB64', b64);

msg.method = 'GET';
msg.url = cfg.aasUrl + '/submodels/' + b64;
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
node.status({ fill: 'blue', shape: 'dot', text: 'reading AAS' });
return msg;

// ═══════════════════════════════════════════════════════════
// MAPPING Odoo -> AAS
// Target: DataSources submodel -> SML "DataSources" -> SMC "ERP"
// The collection sits alongside "Manufacturing", "Simulation" and "PLM"
// as an equal and carries the data source "ERP".
// ═══════════════════════════════════════════════════════════
const erp = flow.get('erp');
const sm = msg.payload;

if (!sm || !Array.isArray(sm.submodelElements)) {
    node.error('The DataSources submodel could not be read', msg);
    return null;
}

const DATA_SOURCE_NAME = 'ERP';
const SMC_ID_SHORT = 'ERP';   // AASd-002: only [a-zA-Z][a-zA-Z0-9_]*

function idShort(str) {
    let s = String(str || '')
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue')
        .replace(/ß/g, 'ss')
        .replace(/[^A-Za-z0-9_]/g, '_')
        .replace(/__+/g, '_').replace(/_+$/, '');
    if (!/^[a-zA-Z]/.test(s)) { s = 'X_' + s; }
    return s.substring(0, 128) || 'Undefined';
}
function prop(id, value, valueType) {
    return { modelType: 'Property', idShort: id,
             valueType: valueType || 'xs:string',
             value: value === null || value === undefined ? '' : String(value) };
}
function smc(id, value) {
    return { modelType: 'SubmodelElementCollection', idShort: id, value: value };
}
function byIdShort(arr, id) {
    return (arr || []).find(e => e && e.idShort === id);
}

// One collection per bill-of-material line
const usedIds = {};
const componentSmcs = erp.components.map(c => {
    let id = idShort(c.name);
    if (usedIds[id]) { usedIds[id] += 1; id = id + '_' + usedIds[id]; } else { usedIds[id] = 1; }
    return smc(id, [
        prop('ComponentName', c.name),
        prop('ProductCode', c.productCode),
        prop('Quantity', c.quantity, 'xs:double'),
        prop('QuantityUnit', c.quantityUnit),
        prop('WeightPerUnit', c.weightKg, 'xs:double'),
        prop('WeightUnit', 'kg'),
        prop('TotalMass', c.totalMassKg, 'xs:double'),
        prop('TotalMassUnit', 'kg'),
        prop('Material', c.material),
        prop('MaterialCategory', c.materialCategory),
        prop('LCAFlowId', c.lcaFlowId),
        prop('LCAProcessId', c.lcaProcessId),
        prop('LCAParameterName', c.lcaParameter),
        prop('LCAZeroParameters', c.lcaZeroParameters)
    ]);
});

const erpValue = [
    prop('DataSource', DATA_SOURCE_NAME),
    prop('SourceSystem', 'Odoo'),
    prop('TimeOfRetrieval', erp.retrievedAt, 'xs:dateTime'),
    prop('ProductName', erp.productName),
    prop('ProductCode', erp.productCode),
    prop('ProductWeight', erp.productWeightKg, 'xs:double'),
    prop('ProductWeightUnit', 'kg'),
    prop('BillOfMaterialId', erp.bomId, 'xs:string'),
    prop('BillOfMaterialQuantity', erp.bomQuantity, 'xs:double'),
    smc('BillOfMaterial', componentSmcs)
];

if (erp.order) {
    erpValue.push(smc('ManufacturingOrder', [
        prop('OrderNumber', erp.order.number),
        prop('OrderQuantity', erp.order.quantity, 'xs:double'),
        prop('OrderUnit', erp.order.unit),
        prop('OrderState', erp.order.state)
    ]));
}

// SML "DataSources" suchen; faellt auf das erste Listenelement zurueck
let list = byIdShort(sm.submodelElements, 'DataSources')
        || byIdShort(sm.submodelElements, 'Data Sources')
        || sm.submodelElements.find(e => e.modelType === 'SubmodelElementList');
if (!list) {
    node.error('SubmodelElementList "DataSources" not found', msg);
    return null;
}
if (!Array.isArray(list.value)) { list.value = []; }

// Replace an existing ERP entry, otherwise append one
const existing = list.value.findIndex(e => e && e.idShort === SMC_ID_SHORT);
const newSmc = smc(SMC_ID_SHORT, erpValue);

// Leave entries that belong to someone else in place.
//
// This flow rebuilds the ERP block. Everything it does not write itself
// was gone with it - including the booked assemblies (AssemblyRecords),
// which another flow puts there. The loss went unnoticed: the ERP row in
// the dashboard stayed green, only the list of manufactured pieces was
// suddenly empty.
//
// Whoever rebuilds a block has to carry over what is not theirs.
if (existing >= 0) {
    const bisher = (list.value[existing] || {}).value || [];   // what is there now
    const eigene = erpValue.map(e => e && e.idShort);
    const fremde = bisher.filter(e => e && eigene.indexOf(e.idShort) < 0);
    newSmc.value = erpValue.concat(fremde);
    list.value[existing] = newSmc;
    node.log('ERP updated'
           + (fremde.length ? ', ' + fremde.length + ' foreign entries kept' : ''));
} else {
    list.value.push(newSmc);
    node.log('ERP newly created');
}

msg.method = 'PUT';
msg.url = flow.get('cfg').aasUrl + '/submodels/' + flow.get('submodelB64');
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = sm;
node.status({ fill: 'blue', shape: 'dot', text: 'schreibe AAS' });
return msg;

// Ergebnis melden
const erp = flow.get('erp') || {};
const code = msg.statusCode;
if (code && code >= 400) {
    node.error('AAS-Schreibvorgang fehlgeschlagen: HTTP ' + code, msg);
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + code });
    return null;
}
const n = (erp.components || []).length;
const order = erp.order ? (', Auftrag ' + erp.order.number) : '';
msg.payload = {
    status: 'ok',
    dataSource: 'ERP',
    product: erp.productName,
    components: n,
    skipped: erp.skipped || [],
    order: erp.order || null,
    retrievedAt: erp.retrievedAt
};
node.status({ fill: 'green', shape: 'dot', text: n + ' Positionen' + order });
node.log('ERP-Daten in AAS geschrieben: ' + n + ' Positionen');
return msg;
